using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Host;
using MiniFramework.Runtime;
using MiniFramework.Providers.Fake;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace MiniFramework.Resources.Tests
{
    public sealed class ResourceContractTests
    {
        private static ResourceKey Key(string version="v1")=>new ResourceKey("fake","main",version,"icon",typeof(string));
        private static ResourceKey SceneKey=>ResourceKey.Scene("fake","main","v1","level");
        private static CleanupContext Cleanup=>new CleanupContext(CancellationToken.None,Timeout.InfiniteTimeSpan);
        private static FrameworkError Error=>new FrameworkError(ErrorKind.Provider,"fake.injected",retry:RetryHint.MayRetry);
        private static FakeAsset<string> Asset(FakeResourceProvider p){p.BeginLoad<string>(Key());var load=p.AssetAt<string>(p.AssetStartCount-1);load.Succeed("value");return load.Asset;}
        private static FakeScene Scene(FakeResourceProvider p,bool active=false){p.BeginLoadScene(SceneKey,new SceneLoadOptions(SceneLoadMode.Additive,active));var load=p.SceneAt(p.SceneStartCount-1);load.Succeed();return load.Scene;}
        [Test] public void CompleteVersionIdentityHasStableEquality(){var a=Key();var b=Key();Assert.AreEqual(a,b);Assert.AreEqual(a.GetHashCode(),b.GetHashCode());Assert.AreEqual(1,new HashSet<ResourceKey>{a,b}.Count);}
        [Test] public void EveryIdentityDimensionParticipates(){var keys=new HashSet<ResourceKey>{Key(),Key("v2"),new ResourceKey("other","main","v1","icon",typeof(string)),new ResourceKey("fake","other","v1","icon",typeof(string)),new ResourceKey("fake","main","v1","ICON",typeof(string)),new ResourceKey("fake","main","v1","icon",typeof(object)),ResourceKey.Scene("fake","main","v1","icon")};Assert.AreEqual(7,keys.Count);}
        [Test] public void DefaultAndIncompleteKeysAreInvalid(){Assert.IsFalse(default(ResourceKey).IsValid);Assert.Throws<ArgumentException>(()=>new ResourceKey("fake","main","","icon",typeof(string)));Assert.Throws<ArgumentException>(()=>new ResourceKey("fake","main","v1","icon",typeof(int)));Assert.Throws<ArgumentException>(()=>new ResourceKey("fake","main","v1","icon",typeof(List<>)));}
        [Test] public void PublicLeasesExposeNoMutableRefCount(){foreach(var type in new[]{typeof(IAssetLease<string>),typeof(ISceneLease)})foreach(var property in type.GetProperties()){Assert.IsNull(property.SetMethod);Assert.AreNotEqual("RefCount",property.Name);}}
        [Test] public void ProviderRejectsWrongKindTypeAndIdentity(){var p=new FakeResourceProvider();Assert.IsFalse(p.BeginLoad<object>(Key()).IsSuccess);Assert.IsFalse(p.BeginLoad<string>(SceneKey).IsSuccess);Assert.IsFalse(p.BeginLoad<string>(default).IsSuccess);Assert.IsFalse(p.BeginLoad<string>(new ResourceKey("other","main","v1","icon",typeof(string))).IsSuccess);Assert.AreEqual(0,p.AssetStartCount);}
        [Test] public void FakeDoesNotPretendToImplementServiceSharing(){var p=new FakeResourceProvider();var a=p.BeginLoad<string>(Key()).Value;var b=p.BeginLoad<string>(Key()).Value;Assert.AreNotSame(a,b);Assert.AreEqual(2,p.AssetStartCount);Assert.AreNotEqual(a.Id,b.Id);}
        [UnityTest] public IEnumerator AssetCompletionIsManuallyControlled()=>UniTask.ToCoroutine(async()=>{var p=new FakeResourceProvider();var op=p.BeginLoad<string>(Key()).Value;Assert.AreEqual(BackendState.Running,op.State);Assert.AreEqual(UniTaskStatus.Pending,op.Completion.Status);p.AssetAt<string>(0).Succeed("a");var result=await op.Completion;Assert.AreEqual("a",result.Value.Value);Assert.AreEqual(BackendState.Succeeded,op.State);});
        [Test] public void DuplicateCompletionCannotReplaceAsset(){var p=new FakeResourceProvider();var a=Asset(p);Assert.IsFalse(p.AssetAt<string>(0).Succeed("replacement"));Assert.AreEqual("value",a.Value);}
        [UnityTest] public IEnumerator FailureAndDefaultResultCannotProduceSuccess()=>UniTask.ToCoroutine(async()=>{var p=new FakeResourceProvider();var op=p.BeginLoad<string>(Key()).Value;p.AssetAt<string>(0).Fail(Error);Assert.AreEqual("fake.injected",(await op.Completion).Error.Code);var second=p.BeginLoad<string>(Key()).Value;p.AssetAt<string>(1).Operation.Complete(default);Assert.AreEqual(ErrorKind.InvalidResult,(await second.Completion).Error.Kind);});
        [Test] public void NullAssetCannotBeAccepted(){var p=new FakeResourceProvider();p.BeginLoad<string>(Key());Assert.Throws<ArgumentNullException>(()=>p.AssetAt<string>(0).Succeed(null));Assert.AreEqual(BackendState.Running,p.AssetAt<string>(0).Operation.State);}
        [UnityTest] public IEnumerator ReleaseRequiresActualConfirmation()=>UniTask.ToCoroutine(async()=>{var a=Asset(new FakeResourceProvider());var op=a.BeginRelease(Cleanup).Value;Assert.AreEqual(AssetLeaseState.Releasing,a.State);Assert.AreEqual(UniTaskStatus.Pending,op.Completion.Status);Assert.Throws<InvalidOperationException>(()=>{var v=a.Value;});a.ReleaseAttempt.Complete(Result<Unit>.Success(default));Assert.IsTrue((await op.Completion).IsSuccess);Assert.AreEqual(AssetLeaseState.Released,a.State);});
        [Test] public void ConcurrentReleaseJoinsButDoubleReturnRejected(){var a=Asset(new FakeResourceProvider());var first=a.BeginRelease(Cleanup).Value;Assert.AreSame(first,a.BeginRelease(default).Value);a.ReleaseAttempt.Complete(Result<Unit>.Success(default));Assert.IsFalse(a.BeginRelease(Cleanup).IsSuccess);Assert.IsFalse(a.RetryRelease(Cleanup).IsSuccess);}
        [UnityTest] public IEnumerator FailedReleaseRequiresExplicitRetryAndPreservesAttempt()=>UniTask.ToCoroutine(async()=>{var a=Asset(new FakeResourceProvider());var first=a.BeginRelease(Cleanup).Value;a.ReleaseAttempt.Complete(Result<Unit>.Failure(Error));Assert.AreEqual(AssetLeaseState.ReleaseFailed,a.State);Assert.IsFalse(a.BeginRelease(Cleanup).IsSuccess);var second=a.RetryRelease(Cleanup).Value;Assert.AreNotSame(first,second);a.ReleaseAttempt.Complete(Result<Unit>.Success(default));Assert.IsFalse((await first.Completion).IsSuccess);Assert.IsTrue((await second.Completion).IsSuccess);});
        [Test] public void CleanupTokenIsIndependentFromBusinessCancellation(){var c=new CancellationTokenSource();c.Cancel();var a=Asset(new FakeResourceProvider());a.BeginRelease(Cleanup);Assert.IsFalse(a.LastCleanup.ShutdownCancellation.IsCancellationRequested);Assert.AreEqual(AssetLeaseState.Releasing,a.State);c.Dispose();}
        [Test] public void ProviderHandlesKeepSelectedVersion(){var p=new FakeResourceProvider();p.BeginLoad<string>(Key("v1"));p.BeginLoad<string>(Key("v2"));p.AssetAt<string>(1).Succeed("new");p.AssetAt<string>(0).Succeed("old");Assert.AreEqual("v1",p.AssetAt<string>(0).Asset.Key.ContentVersion);Assert.AreEqual("old",p.AssetAt<string>(0).Asset.Value);}
        [Test] public void DeferredSceneCapabilityIsExplicit(){var p=new FakeResourceProvider(supportsDeferredActivation:false);var r=p.BeginLoadScene(SceneKey,new SceneLoadOptions(SceneLoadMode.Additive,false));Assert.AreEqual(ErrorKind.NotSupported,r.Error.Kind);Assert.AreEqual(0,p.SceneStartCount);Assert.IsTrue(p.BeginLoadScene(SceneKey,new SceneLoadOptions(SceneLoadMode.Single,true)).IsSuccess);}
        [Test] public void SceneOptionsPreserveSingleAndAdditive(){var p=new FakeResourceProvider();p.BeginLoadScene(SceneKey,new SceneLoadOptions(SceneLoadMode.Single,true));p.SceneAt(0).Succeed();Assert.AreEqual(SceneLoadMode.Single,p.SceneAt(0).Scene.Options.Mode);Assert.AreEqual(SceneLeaseState.Active,p.SceneAt(0).Scene.State);Assert.AreEqual(SceneLoadMode.Additive,Scene(p).Options.Mode);}
        [UnityTest] public IEnumerator ActivationWaitsForActualCompletion()=>UniTask.ToCoroutine(async()=>{var s=Scene(new FakeResourceProvider());Assert.AreEqual(SceneLeaseState.AwaitingActivation,s.State);var op=s.BeginActivation().Value;Assert.AreSame(op,s.BeginActivation().Value);Assert.IsFalse(s.BeginUnload(Cleanup).IsSuccess);s.Activation.Complete(Result<Unit>.Success(default));Assert.IsTrue((await op.Completion).IsSuccess);Assert.AreEqual(SceneLeaseState.Active,s.State);Assert.IsFalse(s.BeginActivation().IsSuccess);});
        [Test] public void ActivationFailureStillOwnsSceneDependencies(){var s=Scene(new FakeResourceProvider());s.BeginActivation();s.Activation.Complete(Result<Unit>.Failure(Error));Assert.AreEqual(SceneLeaseState.Failed,s.State);Assert.IsTrue(s.HoldsDependencies);Assert.IsTrue(s.BeginUnload(Cleanup).IsSuccess);}
        [UnityTest] public IEnumerator UnloadConfirmationIsTheOnlyReleasePoint()=>UniTask.ToCoroutine(async()=>{var s=Scene(new FakeResourceProvider(),true);var op=s.BeginUnload(Cleanup).Value;Assert.IsTrue(s.HoldsDependencies);Assert.AreEqual(SceneLeaseState.Unloading,s.State);Assert.AreSame(op,s.BeginUnload(default).Value);s.Unload.Complete(Result<Unit>.Success(default));await op.Completion;Assert.IsFalse(s.HoldsDependencies);Assert.AreEqual(SceneLeaseState.Released,s.State);Assert.IsFalse(s.BeginUnload(Cleanup).IsSuccess);});
        [Test] public void UnloadFailureRetainsDependenciesAndRequiresRetry(){var s=Scene(new FakeResourceProvider());s.BeginUnload(Cleanup);s.Unload.Complete(Result<Unit>.Failure(Error));Assert.IsTrue(s.HoldsDependencies);Assert.AreEqual(SceneLeaseState.Failed,s.State);Assert.IsFalse(s.BeginUnload(Cleanup).IsSuccess);Assert.IsTrue(s.RetryUnload(Cleanup).IsSuccess);Assert.IsTrue(s.HoldsDependencies);s.Unload.Complete(Result<Unit>.Success(default));Assert.IsFalse(s.HoldsDependencies);}
        [Test] public void DeferredSceneCanUnloadWithoutActivation(){var s=Scene(new FakeResourceProvider());Assert.IsTrue(s.BeginUnload(Cleanup).IsSuccess);s.Unload.Complete(Result<Unit>.Success(default));Assert.IsNull(s.Activation);Assert.IsFalse(s.HoldsDependencies);}
        [Test] public void DuplicateUnloadCompletionCannotChangeReleasedState(){var s=Scene(new FakeResourceProvider());s.BeginUnload(Cleanup);s.Unload.Complete(Result<Unit>.Success(default));Assert.IsFalse(s.Unload.Complete(Result<Unit>.Failure(Error)));Assert.AreEqual(SceneLeaseState.Released,s.State);}
        [Test] public void WaitCancellationDoesNotCompleteProviderOperation(){var p=new FakeResourceProvider();var op=p.BeginLoad<string>(Key()).Value;var h=new HostScheduler();var c=new CancellationTokenSource();var wait=h.Observe(OperationContext.Unlimited(c.Token),_=>{});c.Cancel();h.Pump(0,0);Assert.IsFalse(wait.IsPending);Assert.AreEqual(BackendState.Running,op.State);p.AssetAt<string>(0).Succeed("late");Assert.AreEqual(BackendState.Succeeded,op.State);h.Dispose();c.Dispose();}
        [UnityTest] public IEnumerator ScopeCloseOwnsLateLoadUntilActualRelease()=>UniTask.ToCoroutine(async()=>{var p=new FakeResourceProvider();var op=p.BeginLoad<string>(Key()).Value;var scope=new Scope("owner");scope.RunTask("actual-load-and-release",async _=>{var result=await op.Completion;var release=result.Value.BeginRelease(Cleanup).Value;return (await release.Completion).IsSuccess?Result.Success():Result.Failure(Error);});await scope.CloseAsync(default);Assert.AreEqual(ScopeState.Closing,scope.State);p.AssetAt<string>(0).Succeed("late");await UniTask.Yield();Assert.AreEqual(AssetLeaseState.Releasing,p.AssetAt<string>(0).Asset.State);Assert.AreEqual(ScopeState.Closing,scope.State);p.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));Assert.IsTrue((await scope.CloseAsync(Cleanup)).IsFullyDrained);});
        private sealed class SceneCleanup : IAsyncCleanup
        {
            private readonly FakeScene scene;private bool attempted;public string Id=>"scene-cleanup";
            internal SceneCleanup(FakeScene scene){this.scene=scene;}
            public async UniTask<Result> CleanupAsync(CleanupContext cleanup){var operation=attempted?scene.RetryUnload(cleanup):scene.BeginUnload(cleanup);attempted=true;if(!operation.IsSuccess)return Result.Failure(operation.Error);var result=await operation.Value.Completion;return result.IsSuccess?Result.Success():Result.Failure(result.Error);}
        }
        [UnityTest] public IEnumerator SceneCleanupTicketRetainsFailedUnloadForExplicitRetry()=>UniTask.ToCoroutine(async()=>{var scene=Scene(new FakeResourceProvider());var scope=new Scope("scene-owner");scope.Cleanup.Register(new SceneCleanup(scene));await scope.CloseAsync(default);Assert.IsTrue(scene.HoldsDependencies);scene.Unload.Complete(Result<Unit>.Failure(Error));Assert.IsFalse((await scope.CloseAsync(Cleanup)).IsFullyDrained);var retry=scope.RetryFailedAsync(default);await retry;Assert.IsTrue(scene.HoldsDependencies);scene.Unload.Complete(Result<Unit>.Success(default));Assert.IsTrue((await scope.CloseAsync(Cleanup)).IsFullyDrained);});
        [UnityTest] public IEnumerator OwnerClosingDuringSceneLoadRetainsUntilUnloadConfirmed()=>UniTask.ToCoroutine(async()=>
        {
            var p=new FakeResourceProvider();var op=p.BeginLoadScene(SceneKey,new SceneLoadOptions(SceneLoadMode.Additive,false)).Value;var owner=new Scope("late-scene");
            owner.RunTask("scene-drain",async _=>{var loaded=await op.Completion;var unload=loaded.Value.BeginUnload(Cleanup).Value;var result=await unload.Completion;return result.IsSuccess?Result.Success():Result.Failure(result.Error);});
            await owner.CloseAsync(default);Assert.AreEqual(BackendState.Running,op.State);p.SceneAt(0).Succeed();await UniTask.Yield();var scene=p.SceneAt(0).Scene;
            Assert.AreEqual(SceneLeaseState.Unloading,scene.State);Assert.IsTrue(scene.HoldsDependencies);Assert.AreEqual(ScopeState.Closing,owner.State);
            scene.Unload.Complete(Result<Unit>.Success(default));Assert.IsTrue((await owner.CloseAsync(Cleanup)).IsFullyDrained);Assert.IsFalse(scene.HoldsDependencies);
        });
        [UnityTest] public IEnumerator OwnerClosingDuringActivationWaitsThenUnloads()=>UniTask.ToCoroutine(async()=>
        {
            var scene=Scene(new FakeResourceProvider());var activation=scene.BeginActivation().Value;var owner=new Scope("activation-owner");
            owner.RunTask("activation-drain",async _=>{await activation.Completion;var unload=scene.BeginUnload(Cleanup).Value;var result=await unload.Completion;return result.IsSuccess?Result.Success():Result.Failure(result.Error);});
            await owner.CloseAsync(default);Assert.IsNull(scene.Unload);Assert.IsTrue(scene.HoldsDependencies);scene.Activation.Complete(Result<Unit>.Success(default));await UniTask.Yield();
            Assert.AreEqual(SceneLeaseState.Unloading,scene.State);Assert.AreEqual(ScopeState.Closing,owner.State);scene.Unload.Complete(Result<Unit>.Success(default));Assert.IsTrue((await owner.CloseAsync(Cleanup)).IsFullyDrained);
        });
        [Test] public void InvalidSceneKeysDoNotStartOperations(){var p=new FakeResourceProvider();Assert.IsFalse(p.BeginLoadScene(Key(),default).IsSuccess);Assert.IsFalse(p.BeginLoadScene(default,default).IsSuccess);Assert.AreEqual(0,p.SceneStartCount);Assert.Throws<ArgumentOutOfRangeException>(()=>new SceneLoadOptions((SceneLoadMode)99,true));}
        [Test] public void FakeRejectsWorkerThreadCompletion(){var p=new FakeResourceProvider();p.BeginLoad<string>(Key());Exception error=null;var t=new Thread(()=>{try{p.AssetAt<string>(0).Succeed("worker");}catch(Exception e){error=e;}});t.Start();t.Join();Assert.IsInstanceOf<InvalidOperationException>(error);Assert.AreEqual(BackendState.Running,p.AssetAt<string>(0).Operation.State);}
    }
}
